What will be printed by the parent process and the child process?

```c
int x = 8;
void *decrement(void *arg) {
    int *data = arg;
    x -= *data;
    return NULL;
}
void *increment(void *arg) {
    int *data = arg;
    x += *data;
    return NULL;
}
int main(int argc, char *argv[]) {
    pid_t pid;
    pthread_t tid1, tid2;
    pthread_attr_t attr1, attr2;
    int num1 = 3, num2 = 2;

    printf("INITIAL: x = %d\n", x);
    fflush(stdout);

    pid = fork();
    if (pid > 0) { /* Parent Process */
        pthread_attr_init(&attr1);
        pthread_create(&tid1, &attr1, decrement, &num1);
        pthread_join(tid1, NULL);
        printf("PARENT: x = %d\n", x);
    } else if (pid == 0) { /* Child Process */
        pthread_attr_init(&attr2);
        pthread_create(&tid2, &attr2, increment, &num2);
        pthread_join(tid2, NULL);
        printf("CHILD: x = %d\n", x);
    }
    return 0;
}
```

Derive the outputs for `PARENT: x = ...` and `CHILD: x = ...`.

```c
int x = 5;
void *subtract(void *arg) {
    int *data = arg;
    x -= *data;
    return NULL;
}
void *multiply(void *arg) {
    int *data = arg;
    x *= *data;
    return NULL;
}
int main(int argc, char *argv[]) {
    pid_t pid;
    pthread_t tid1, tid2;
    int num1 = 3, num2 = 4;

    pid = fork();
    if (pid > 0) { /* Parent */
        pthread_create(&tid1, NULL, subtract, &num1);
        pthread_join(tid1, NULL);
        printf("PARENT: x = %d\n", x);
    } else if (pid == 0) { /* Child */
        pthread_create(&tid2, NULL, multiply, &num2);
        pthread_join(tid2, NULL);
        printf("CHILD: x = %d\n", x);
    }
    return 0;
}
```
